"""The live claim gate section: real patterns, run in the visitor's browser.

Generated markup + script. The patterns come from _data/gate_patterns.json,
which is exported from backend/adkit/gate.py in the app repo — see
scripts/export_gate_patterns.py and tests/test_gate_export.py there, which
runs the same strings through Python and node and fails if they disagree.
"""

SECTION = '\n<section class="livegate" id="try">\n  <p class="eyebrow">Try the claim gate</p>\n  <h2>Paste an ad claim. Watch it get checked.</h2>\n  <p class="livegate-lede">This is the real gate — the same thirteen patterns\n  the app runs, exported from the engine, not a reproduction. Nothing is sent\n  anywhere; it runs in this page.</p>\n\n  <div class="lg-grid">\n    <label class="lg-field">\n      <span>Your ad copy</span>\n      <textarea id="lg-claim" rows="4" spellcheck="false">Trusted by 4,000 businesses. Get paid 10x faster. Starting at $29/month.</textarea>\n    </label>\n    <label class="lg-field">\n      <span>Text from your website</span>\n      <textarea id="lg-source" rows="4" spellcheck="false">HoneyBook helps independent businesses manage clients, projects and payments in one place. Plans from $19/month.</textarea>\n    </label>\n  </div>\n\n  <div class="lg-out" id="lg-out" aria-live="polite"></div>\n  <p class="lg-foot">A claim it cannot trace to your own page is blocked before\n  it reaches an ad account. That is the whole product; this is it running.</p>\n</section>\n'

SCRIPT = '\n<script id="lg-data" type="application/json">{"_note":"Generated by scripts/export_gate_patterns.py from backend/adkit/gate.py. Do not edit by hand \\u2014 tests/test_gate_export.py fails when this drifts from the engine.","figure_re":"[$\\u00a3\\u20ac]?\\\\d[\\\\d,.]*\\\\s*(?:k\\\\b|m\\\\b|bn\\\\b|b\\\\b|x\\\\b|%|\\\\+)?","claim_patterns":[{"pattern":"\\\\b\\\\d[\\\\d,.]*\\\\s?(?:k|m|\\\\+|million|thousand|%)?\\\\s+(?:customers?|clients?|users?|teams?|businesses|companies|reviews?|stars?|years?|countries|downloads?|installs?)\\\\b","label":"a quantity of people or time"},{"pattern":"\\\\btrusted by\\\\b|\\\\bloved by\\\\b|\\\\bused by\\\\b|\\\\bjoin \\\\d","label":"social proof"},{"pattern":"\\\\b(?:no\\\\.?\\\\s?1|#1|the (?:best|leading|top|only|fastest|largest))\\\\b","label":"a superlative"},{"pattern":"\\\\b(?:award[- ]winning|voted|rated|certified|accredited|licen[cs]ed)\\\\b","label":"a credential"},{"pattern":"\\\\b(?:guarantee[ds]?|money[- ]back|risk[- ]free|refund)\\\\b","label":"a guarantee"},{"pattern":"\\\\b(?:in|within|under)\\\\s+\\\\d+\\\\s?(?:min|minute|hour|day|week|second)","label":"a speed promise"},{"pattern":"\\\\b(?:free|save|from)\\\\s*[$\\u00a3\\u20ac]\\\\s?\\\\d|[$\\u00a3\\u20ac]\\\\s?\\\\d[\\\\d,.]*","label":"a price"},{"pattern":"\\\\b\\\\d[\\\\d,.]*\\\\s?%","label":"a percentage"},{"pattern":"\\\\b(?:save|cut|reduce|increase|grow|double|triple)\\\\s+(?:your\\\\s+)?\\\\w+\\\\s+by\\\\b","label":"a quantified outcome"},{"pattern":"\\\\b\\\\d+\\\\s?x\\\\s+(?:faster|quicker|more|less|better|cheaper|higher|bigger)","label":"a performance multiplier"},{"pattern":"\\\\b(?:twice|thrice|three times|four times|double|triple|half)\\\\s+(?:as\\\\s+)?(?:fast|quick|many|much|long|the)\\\\b","label":"a performance multiplier"},{"pattern":"\\\\b(?:faster|quicker|cheaper|better|easier|simpler|more)\\\\s+than\\\\b","label":"a comparison to something else"},{"pattern":"\\\\b(?:instantly|overnight|in seconds|same[- ]day|next[- ]day)\\\\b","label":"a speed promise"}]}</script>\n<script>\n/* The live claim gate.\n *\n * The patterns are EXPORTED from backend/adkit/gate.py and a test in the app\n * repo runs the same strings through Python\'s `re` and node\'s RegExp and fails\n * if the verdicts differ. So this is the engine\'s rule, not a reproduction of\n * it — which matters, because a page that fakes its own product\'s output is\n * the exact thing this product exists to catch.\n *\n * The figure trace is the gate\'s second half: a number in the ad must appear\n * in text the crawler actually read. Bounded so "20" is not satisfied by\n * "120", same as _figure_is_present.\n */\n(function(){\n  var el = document.getElementById(\'lg-out\');\n  if (!el) return;\n  var data = JSON.parse(document.getElementById(\'lg-data\').textContent);\n  var claimEl = document.getElementById(\'lg-claim\');\n  var srcEl = document.getElementById(\'lg-source\');\n  var FIG = new RegExp(data.figure_re, \'gi\');\n\n  function figures(text){\n    var out = [], m;\n    FIG.lastIndex = 0;\n    while ((m = FIG.exec(text)) !== null) {\n      var raw = m[0].trim().toLowerCase()\n        .replace(/^[$£€]/, \'\').replace(/[.,]+$/, \'\').replace(/,/g, \'\');\n      if (raw && /\\d/.test(raw)) out.push(raw);\n      if (m.index === FIG.lastIndex) FIG.lastIndex++;\n    }\n    return out;\n  }\n  function present(fig, source){\n    var bare = fig.replace(/[kmbx%+]+$/, \'\').replace(/\\.$/, \'\');\n    if (!bare) return false;\n    return new RegExp(\'(?<!\\\\d)\' + bare.replace(/[.*+?^${}()|[\\]\\\\]/g,\'\\\\$&\') + \'(?!\\\\d)\')\n      .test(source);\n  }\n  function esc(s){ return s.replace(/[&<>]/g, function(c){\n    return {\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\'}[c]; }); }\n\n  function run(){\n    var claim = claimEl.value, source = srcEl.value;\n    var rows = [];\n    /* Widen each match to its surrounding sentence before tracing figures —\n       a faithful port of _find_undeclared in gate.py, including MAX_SPAN=160.\n       Using the bare regex match instead was a real bug caught by running\n       this: the price pattern matches only "from $1" of "from $19/month", so\n       the figure traced was "1" and a price that IS on the advertiser\'s page\n       came back BLOCKED. That is the page showing a verdict the engine does\n       not give, on the one product whose pitch is that it proves its claims. */\n    var MAX_SPAN = 160;\n    data.claim_patterns.forEach(function(p){\n      var re = new RegExp(p.pattern, \'gi\'), m;\n      while ((m = re.exec(claim)) !== null) {\n        var start = Math.max(\n          claim.lastIndexOf(\'.\', m.index - 1) + 1,\n          claim.lastIndexOf(\'!\', m.index - 1) + 1,\n          claim.lastIndexOf(\'?\', m.index - 1) + 1,\n          m.index - MAX_SPAN, 0);\n        var endsAt = [\'.\', \'!\', \'?\']\n          .map(function(ch){ return claim.indexOf(ch, m.index + m[0].length); })\n          .filter(function(i){ return i !== -1; });\n        var end = endsAt.length ? Math.min.apply(null, endsAt) : claim.length;\n        end = Math.min(end, m.index + m[0].length + MAX_SPAN);\n        var span = claim.slice(start, end).replace(/^[\\s.,!?]+|[\\s.,!?]+$/g, \'\');\n        if (span) rows.push({ text: span, why: p.label });\n        if (m.index === re.lastIndex) re.lastIndex++;\n      }\n    });\n    var seen = {}, uniq = [];\n    rows.forEach(function(r){ var k = r.text.toLowerCase();\n      if (!seen[k]) { seen[k] = 1; uniq.push(r); } });\n\n    var blocked = 0, html = \'\';\n    uniq.forEach(function(r){\n      var figs = figures(r.text);\n      var missing = figs.filter(function(f){ return !present(f, source); });\n      var ok = missing.length === 0;\n      if (!ok) blocked++;\n      html += \'<div class="lg-row \' + (ok ? \'ok\' : \'bad\') + \'">\' +\n        \'<span class="lg-ic">\' + (ok ? \'✓\' : \'×\') + \'</span><span>\' +\n        \'<strong>\' + esc(r.text) + \'</strong>\' +\n        \'<span class="lg-why">\' + esc(r.why) +\n        (ok ? (figs.length ? \' — traced to your page\'\n                           : \' — needs a source on your page\')\n            : \' — \' + esc(missing.join(\', \')) +\n              \' appears nowhere in the text you gave\') +\n        \'</span></span></div>\';\n    });\n\n    if (!uniq.length) {\n      html = \'<div class="lg-row ok"><span class="lg-ic">✓</span><span>\' +\n        \'<strong>Nothing here needs substantiating</strong>\' +\n        \'<span class="lg-why">No price, superlative, guarantee, statistic or \' +\n        \'performance promise found. That is a pass, not an endorsement.</span>\' +\n        \'</span></div>\';\n    }\n    var verdict = blocked\n      ? \'<p class="lg-verdict bad">BLOCKED — \' + blocked +\n        (blocked === 1 ? \' claim\' : \' claims\') + \' could not be traced.</p>\'\n      : \'<p class="lg-verdict ok">\' + uniq.length +\n        (uniq.length === 1 ? \' claim\' : \' claims\') + \' checked, all traced.</p>\';\n    el.innerHTML = verdict + html;\n  }\n\n  claimEl.addEventListener(\'input\', run);\n  srcEl.addEventListener(\'input\', run);\n  run();\n})();\n</script>\n'
